import { Audio, staticFile } from 'remotion';
/** Sound effects (generated by scripts/score.mjs; original, no third-party samples). Placed by scenes at the frames of recorded events. */
export function Sfx({ name, volume = 0.5 }: { name: 'click' | 'tick' | 'chime' | 'stop'; volume?: number }) {
  return <Audio src={staticFile(`audio/sfx/${name}.wav`)} volume={volume} />;
}
